<?php
declare(strict_types=1);
require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('payments.manage');
$id=max(0,(int)($_GET['id']??$_POST['id']??0));$chargeId=max(0,(int)($_GET['charge_id']??$_POST['charge_id']??0));$payment=null;if($id){$stmt=db()->prepare('SELECT * FROM payments WHERE id=?');$stmt->execute([$id]);$payment=$stmt->fetch();if(!$payment){http_response_code(404);exit('Ingreso no encontrado.');}}
$pageTitle=$payment?'Editar ingreso':'Registrar ingreso';$pdo=db();$clients=$pdo->query("SELECT id,company_name,country FROM clients WHERE status<>'inactive' ORDER BY COALESCE(NULLIF(country,''),'Sin país'),company_name")->fetchAll();$services=$pdo->query("SELECT s.id,s.client_id,s.name,c.company_name FROM client_services s JOIN clients c ON c.id=s.client_id ORDER BY c.company_name,s.name")->fetchAll();$quotes=$pdo->query("SELECT q.id,q.client_id,q.quotation_number,q.currency,q.total,c.company_name FROM quotations q JOIN clients c ON c.id=q.client_id ORDER BY q.issue_date DESC,q.id DESC LIMIT 500")->fetchAll();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$data=['client_id'=>(int)($_POST['client_id']??0),'service_id'=>!empty($_POST['service_id'])?(int)$_POST['service_id']:null,'quotation_id'=>!empty($_POST['quotation_id'])?(int)$_POST['quotation_id']:null,'payment_date'=>(string)($_POST['payment_date']??date('Y-m-d')),'amount'=>(float)($_POST['amount']??0),'currency'=>(string)($_POST['currency']??'USD'),'payment_method'=>trim((string)($_POST['payment_method']??'')),'reference'=>trim((string)($_POST['reference']??'')),'notes'=>trim((string)($_POST['notes']??''))];if(!$data['client_id'])$errors[]='Selecciona un cliente.';if($data['amount']<=0)$errors[]='El valor debe ser mayor que cero.';if(!in_array($data['currency'],['CLP','USD','BRL'],true))$data['currency']='USD';if(!$data['payment_date'])$errors[]='Indica la fecha del ingreso.';
if(!$errors){if($payment){$pdo->prepare('UPDATE payments SET client_id=?,service_id=?,quotation_id=?,payment_date=?,amount=?,currency=?,payment_method=?,reference=?,notes=? WHERE id=?')->execute([...array_values($data),$id]);flash('success','Ingreso actualizado.');}else{$pdo->prepare('INSERT INTO payments(client_id,service_id,quotation_id,payment_date,amount,currency,payment_method,reference,notes,created_by) VALUES (?,?,?,?,?,?,?,?,?,?)')->execute([...array_values($data),(int)$_SESSION['user_id']]);$id=(int)$pdo->lastInsertId();flash('success','Ingreso registrado.');}if($data['service_id']&&!$payment){
    $fullyPaid=true;
    if(db_table_exists('billing_charges')){
        if(!$chargeId){$cs=$pdo->prepare("SELECT id FROM billing_charges WHERE service_id=? AND status IN ('pending','overdue','partial') ORDER BY due_date ASC LIMIT 1");$cs->execute([$data['service_id']]);$chargeId=(int)($cs->fetchColumn()?:0);}
        if($chargeId){
            $cs=$pdo->prepare('SELECT amount,paid_amount FROM billing_charges WHERE id=? AND service_id=?');$cs->execute([$chargeId,$data['service_id']]);$charge=$cs->fetch();
            if($charge){$newPaid=(float)$charge['paid_amount']+(float)$data['amount'];$fullyPaid=$newPaid+0.00001>=(float)$charge['amount'];$pdo->prepare("UPDATE billing_charges SET status=?,paid_amount=?,paid_at=?,payment_id=? WHERE id=?")->execute([$fullyPaid?'paid':'partial',$newPaid,$fullyPaid?$data['payment_date']:null,$id,$chargeId]);}
        }
    }
    if($fullyPaid){$pdo->prepare("UPDATE client_services SET payment_status='paid',paid_at=?,billing_status='paid' WHERE id=?")->execute([$data['payment_date'],$data['service_id']]);billing_advance_service((int)$data['service_id'],$data['payment_date']);}
    else{$pdo->prepare("UPDATE client_services SET payment_status='partial',billing_status='partial' WHERE id=?")->execute([$data['service_id']]);}
}log_activity($payment?'Ingreso actualizado':'Ingreso registrado',$data['client_id'],$data['service_id'],$data['currency'].' '.$data['amount'],$data['quotation_id']);redirect('payments.php');}}
$v=fn(string$key,mixed$default='')=>$_POST[$key]??($payment[$key]??($_GET[$key]??$default));require __DIR__.'/includes/header.php';
?>
<?php foreach($errors as$error):?><div class="alert alert-error"><?=e($error)?></div><?php endforeach;?><form method="post" class="panel"><div class="panel-header"><div><h2><?=$payment?'Actualizar ingreso':'Nuevo ingreso'?></h2><span class="table-sub">El registro se utiliza para los gráficos financieros del dashboard.</span></div><a class="btn btn-light btn-small" href="payments.php">Cancelar</a></div><div class="panel-body form-grid"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="charge_id" value="<?=$chargeId?>"><label>Cliente *<select name="client_id" required><option value="">Seleccionar</option><?php foreach($clients as$c):?><option value="<?=(int)$c['id']?>" <?=(int)$v('client_id')===(int)$c['id']?'selected':''?>><?=e(($c['country']?:'Sin país').' · '.$c['company_name'])?></option><?php endforeach;?></select></label><label>Fecha *<input type="date" name="payment_date" required value="<?=e($v('payment_date',date('Y-m-d')))?>"></label><label>Servicio relacionado<select name="service_id"><option value="">Sin servicio</option><?php foreach($services as$s):?><option value="<?=(int)$s['id']?>" <?=(int)$v('service_id')===(int)$s['id']?'selected':''?>><?=e($s['company_name'].' · '.$s['name'])?></option><?php endforeach;?></select></label><label>Cotización relacionada<select name="quotation_id"><option value="">Sin cotización</option><?php foreach($quotes as$q):?><option value="<?=(int)$q['id']?>" <?=(int)$v('quotation_id')===(int)$q['id']?'selected':''?>><?=e($q['quotation_number'].' · '.$q['company_name'])?></option><?php endforeach;?></select></label><label>Moneda<select name="currency"><option value="CLP" <?=$v('currency')==='CLP'?'selected':''?>>CLP</option><option value="USD" <?=$v('currency','USD')==='USD'?'selected':''?>>USD</option><option value="BRL" <?=$v('currency')==='BRL'?'selected':''?>>BRL</option></select></label><label>Valor *<input type="number" min="0.01" step="0.01" name="amount" required value="<?=e($v('amount'))?>"></label><label>Método de pago<input name="payment_method" value="<?=e($v('payment_method'))?>" placeholder="Transferencia, PIX, Stripe..."></label><label>Referencia<input name="reference" value="<?=e($v('reference'))?>" placeholder="Número de operación o factura"></label><label class="full">Notas<textarea name="notes"><?=e($v('notes'))?></textarea></label><div class="full form-actions"><a class="btn btn-light" href="payments.php">Cancelar</a><button class="btn btn-primary">GUARDAR INGRESO</button></div></div></form>
<?php require __DIR__.'/includes/footer.php';?>
